<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    resumeAfterLogin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">restartAfterIntervention</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
